const postAuth=async(path,payload)=>{const response=await fetch(path,{method:"POST",credentials:"same-origin",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||"Authentication request failed.");return data};
const exchangeNeonSession=async()=>{const tokenResponse=await fetch(`${authUrl.replace(/\/$/,"")}/token`,{method:"GET",credentials:"include",headers:{"Accept":"application/json"}});const tokenData=await tokenResponse.json().catch(()=>({}));const token=typeof tokenData==="string"?tokenData:tokenData.token||tokenData.access_token||tokenData.data?.token||tokenData.data?.access_token||tokenData.session?.access_token;if(!tokenResponse.ok)throw new Error(tokenData.message||tokenData.error||`Neon JWT request failed (HTTP ${tokenResponse.status}).`);if(!token||typeof token!=="string")throw new Error("Neon did not return a session token. Sign in again and retry.");const response=await fetch("/api/auth/neon-session",{method:"POST",headers:{"Content-Type":"application/json","Authorization":"Bearer "+token},credentials:"same-origin"});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||"This verified email is not authorized as the portal administrator.");setAuth(data.user);setAuthStage("login");setAuthPassword("");setAuthError("");setAuthNotice("");};
