const saveSalary=async(row,value=drafts[salaryKey(row)])=>{const ref=row.ref,key=salaryKey(row),amount=String(value??"").trim();if(!/^\d{1,10}(\\.\d{1,2})?$/.test(amount)||Number(amount)<0){setNotice("Enter a valid monthly salary for staff reference "+ref+".");return}setBusy(p=>({...p,[key]:true}));setNotice("");try{const res=await fetch("/api/transport-salaries",{method:"PUT",credentials:"same-origin",headers:{"Content-Type":"application/json"},body:JSON.stringify({region:row.region,staffRef:ref,monthlySalary:amount})});const data=await res.json().catch(()=>({}));if(!res.ok)throw new Error(data.error||"Could not save monthly salary.");const v=String(data.salary.monthly_salary);setSalaries(p=>({...p,[key]:v}));setDrafts(p=>({...p,[key]:v}));setNotice("Monthly salary saved for "+row.name+".")}catch(e){setNotice(e.message)}finally{setBusy(p=>({...p,[key]:false}))}};
