function Coop(){
const months=["July","August","September","October","November","December"];
const [selectedMonth,setSelectedMonth]=useState("July");
const [searchMember,setSearchMember]=useState("");
const [baseMembers,setBaseMembers]=useState(()=>{try{const saved=window.localStorage.getItem("pwfb-coop-members-v1");const parsed=saved?JSON.parse(saved):null;if(Array.isArray(parsed))return parsed;}catch{}return coopAugust.map(m=>({...m}));});
const [monthly,setMonthly]=useState(()=>{try{const saved=window.localStorage.getItem("pwfb-coop-monthly-v1");const parsed=saved?JSON.parse(saved):null;if(parsed&&typeof parsed==="object")return {...Object.fromEntries(months.slice(1).map(month=>[month,{}])),...parsed};}catch{}return Object.fromEntries(months.slice(1).map(month=>[month,{}]));});
const [openMember,setOpenMember]=useState({});
const [notice,setNotice]=useState("");
const [memberForm,setMemberForm]=useState(null);
useEffect(()=>{try{window.localStorage.setItem("pwfb-coop-members-v1",JSON.stringify(baseMembers));window.localStorage.setItem("pwfb-coop-monthly-v1",JSON.stringify(monthly));}catch{}},[baseMembers,monthly]);
const moneyCell=value=>Number(value||0).toLocaleString("en-NG");
const parseAmount=value=>Math.max(0,Number(String(value??0).replace(/,/g,""))||0);
const julyRows=baseMembers.map(m=>({...m,openingSaving:m.savingOpening,savingClosing:m.savingClosing,openingLoan:m.loanOpening,loanClosing:m.loanClosing,loanCollection:m.loanCollection,savingCollection:m.savingCollection,savingWithdrawal:m.savingWithdrawal,loanPaid:m.loanPaid}));
const rowsForMonth=month=>{
 let rows=julyRows;
 for(const step of months.slice(1,months.indexOf(month)+1)){
   rows=rows.map(prev=>{
     // Reuse July's savings and loan collection amounts as each month's defaults.
     // A month-specific entry overrides its defaults when the user changes an amount.
     const source=julyRows.find(member=>member.sn===prev.sn)||prev;
     const entry={
       savingCollection:source.savingCollection,
       savingWithdrawal:0,
       loanCollection:source.loanCollection,
       loanPaid:source.loanPaid,
       newLoan:0,
       ...(monthly[step]?.[prev.sn]||{})
     };
     const openingSaving=Number(prev.savingClosing||0);
     const savingCollection=parseAmount(entry.savingCollection);
     const savingWithdrawal=parseAmount(entry.savingWithdrawal);
     const openingLoan=Number(prev.loanClosing||0);
     const loanCollection=parseAmount(entry.loanCollection);
     const loanPaid=parseAmount(entry.loanPaid);
     const newLoan=parseAmount(entry.newLoan);
     const savingClosing=Math.max(0,openingSaving+savingCollection-savingWithdrawal);
     const loanClosing=Math.max(0,openingLoan+newLoan-loanCollection-loanPaid);
     return {...prev,openingSaving,savingCollection,savingWithdrawal,savingClosing,openingLoan,loanCollection,loanPaid,newLoan,loanClosing};
   });
 }
 return rows;
};
const displayedRows=rowsForMonth(selectedMonth);
const filtered=displayedRows.filter(r=>(String(r.sn)+" "+r.name).toLowerCase().includes(searchMember.toLowerCase()));
const updateEntry=(sn,field,value)=>{
 if(!/^(savingCollection|savingWithdrawal|loanCollection|loanPaid|newLoan)$/.test(field))return;
 const amount=String(value??"").trim()===""?0:Number(value);
 if(!Number.isFinite(amount)||amount<0){setNotice("Enter a valid non-negative amount.");return;}
 setMonthly(prev=>({...prev,[selectedMonth]:{...(prev[selectedMonth]||{}),[sn]:{...(prev[selectedMonth]?.[sn]||{}),[field]:amount}}}));
 setNotice("Updated "+selectedMonth+" figures. Balances and payment status recalculated automatically.");
};
const startAddMember=()=>setMemberForm({mode:"add",sn:"",name:"",savingOpening:"0",loanOpening:"0",remark:"-"});
const editMember=(sn)=>{const m=baseMembers.find(x=>x.sn===sn);if(!m)return;setMemberForm({mode:"edit",sn:m.sn,name:m.name,savingOpening:String(m.savingOpening??0),loanOpening:String(m.loanOpening??0),remark:m.remark||"-"});};
const saveMember=(event)=>{event.preventDefault();if(!memberForm)return;const name=String(memberForm.name||"").trim().replace(/\s+/g," ");const savingOpening=Number(memberForm.savingOpening);const loanOpening=Number(memberForm.loanOpening);if(!name||!Number.isFinite(savingOpening)||savingOpening<0||!Number.isFinite(loanOpening)||loanOpening<0){setNotice("Enter a member name and valid non-negative opening balances.");return;}if(memberForm.mode==="add"){const sn=Math.max(0,...baseMembers.map(m=>Number(m.sn)||0))+1;const added={sn,name,savingOpening,savingCollection:0,savingWithdrawal:0,savingClosing:savingOpening,loanOpening,loanCollection:0,loanPaid:0,loanClosing:loanOpening,remark:String(memberForm.remark||"-").trim()||"-"};setBaseMembers(prev=>[...prev,added]);setNotice(name+" added to the cooperative schedule.");}else{setBaseMembers(prev=>prev.map(m=>m.sn===memberForm.sn?{...m,name,savingOpening,savingClosing:Math.max(0,savingOpening+Number(m.savingCollection||0)-Number(m.savingWithdrawal||0)),loanOpening,loanClosing:Math.max(0,loanOpening+Number(m.newLoan||0)-Number(m.loanCollection||0)-Number(m.loanPaid||0)),remark:String(memberForm.remark||"-").trim()||"-"}:m));setNotice(name+" updated.");}setMemberForm(null);};
const deleteMember=(sn)=>{const m=baseMembers.find(x=>x.sn===sn);if(m&&window.confirm("Delete "+m.name+" from the cooperative schedule on this device? This also removes this member's monthly overrides on this device.")){setBaseMembers(prev=>prev.filter(x=>x.sn!==sn));setMonthly(prev=>Object.fromEntries(Object.entries(prev).map(([month,entries])=>{const next={...entries};delete next[sn];return [month,next];})));setNotice(m.name+" removed from this device's cooperative schedule.");}};
const exportSheet=()=>{
 const rows=[["S/N","Member Name","Month","Opening Savings","Savings Collection","Savings Withdrawal","Closing Savings","Opening Loan","New Loan","Loan Collection / Repayment","Additional Loan Paid","Closing Loan","Payment Status","Remark"],...filtered.map(r=>[r.sn,r.name,selectedMonth,r.openingSaving,r.savingCollection,r.savingWithdrawal,r.savingClosing,r.openingLoan,r.newLoan||0,r.loanCollection,r.loanPaid,r.loanClosing,r.loanClosing<=0?"FULL PAYMENT":"OUTSTANDING",r.remark])];
 const cell=v=>{const x=String(v??"");return /[",\r\n]/.test(x)?'"'+x.replace(/"/g,'""')+'"':x};
 const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([rows.map(row=>row.map(cell).join(",")).join("\r\n")],{type:"text/csv;charset=utf-8"}));a.download="pwfb-cooperative-"+selectedMonth.toLowerCase()+"-2026.csv";a.click();URL.revokeObjectURL(a.href);
};
const totals=filtered.reduce((a,r)=>({savingOpening:a.savingOpening+Number(r.openingSaving||0),savingCollection:a.savingCollection+Number(r.savingCollection||0),savingWithdrawal:a.savingWithdrawal+Number(r.savingWithdrawal||0),savingClosing:a.savingClosing+Number(r.savingClosing||0),loanOpening:a.loanOpening+Number(r.openingLoan||0),newLoan:a.newLoan+Number(r.newLoan||0),loanCollection:a.loanCollection+Number(r.loanCollection||0),loanPaid:a.loanPaid+Number(r.loanPaid||0),loanClosing:a.loanClosing+Number(r.loanClosing||0)}),{savingOpening:0,savingCollection:0,savingWithdrawal:0,savingClosing:0,loanOpening:0,newLoan:0,loanCollection:0,loanPaid:0,loanClosing:0});
return <div className="coop-ledger-page"><div className="coop-ledger-heading"><div><p className="coop-eyebrow">COOPERATIVE SCHEDULE · 2026</p><h2>PWFB Cooperative — Savings &amp; Loan Schedule</h2><p>July is the source schedule. August through December are added automatically with balances carried forward month by month.</p></div><button type="button" className="coop-export-button" onClick={exportSheet}>Export {selectedMonth} CSV</button></div>
<div className="coop-month-switch" role="group" aria-label="Choose cooperative month">{months.map(month=><button key={month} type="button" className={selectedMonth===month?"selected":""} aria-pressed={selectedMonth===month} onClick={()=>{setSelectedMonth(month);setNotice("");}}>{month} 2026</button>)}</div>
<div className="coop-summary-grid"><div><span>Members in schedule</span><strong>{baseMembers.length}</strong><small>{selectedMonth} 2026</small></div><div><span>Opening loan balance</span><strong>₦{moneyCell(totals.loanOpening)}</strong></div><div><span>Loan collections / repayments</span><strong>₦{moneyCell(totals.loanCollection)}</strong><small>{selectedMonth} 2026</small></div><div><span>Closing loan balance</span><strong>₦{moneyCell(totals.loanClosing)}</strong><small>Recalculated automatically</small></div></div>
<div className="coop-summary-grid"><div><span>Opening savings</span><strong>₦{moneyCell(totals.savingOpening)}</strong></div><div><span>Savings collection</span><strong>₦{moneyCell(totals.savingCollection)}</strong></div><div><span>Savings withdrawal</span><strong>₦{moneyCell(totals.savingWithdrawal)}</strong></div><div><span>Closing savings</span><strong>₦{moneyCell(totals.savingClosing)}</strong></div></div>
{notice&&<p className="salary-entry-notice" role="status">{notice}</p>}
<div className="coop-table-toolbar"><label className="coop-search">Search member<input value={searchMember} onChange={e=>setSearchMember(e.target.value)} placeholder="Serial number or member name"/></label><div className="coop-toolbar-actions"><span>{filtered.length} members shown</span><button type="button" className="coop-add-button" onClick={startAddMember}>＋ Add member</button></div></div>
{memberForm&&<form className="coop-member-form" onSubmit={saveMember}><div className="coop-form-heading"><div><span>{memberForm.mode==="add"?"NEW MEMBER":"EDIT MEMBER"}</span><strong>{memberForm.mode==="add"?"Add a cooperative member":"Update member details"}</strong></div><button type="button" className="coop-cancel-button" onClick={()=>setMemberForm(null)}>Cancel</button></div><label>Full name<input required maxLength="120" value={memberForm.name} onChange={e=>setMemberForm(v=>({...v,name:e.target.value}))} placeholder="Member full name"/></label><label>Opening savings (₦)<input required type="number" min="0" step="0.01" value={memberForm.savingOpening} onChange={e=>setMemberForm(v=>({...v,savingOpening:e.target.value}))}/></label><label>Opening loan (₦)<input required type="number" min="0" step="0.01" value={memberForm.loanOpening} onChange={e=>setMemberForm(v=>({...v,loanOpening:e.target.value}))}/></label><label>Remark<input maxLength="240" value={memberForm.remark} onChange={e=>setMemberForm(v=>({...v,remark:e.target.value}))} placeholder="Optional note"/></label><div className="coop-form-actions"><button type="submit" className="coop-add-button">{memberForm.mode==="add"?"Save member":"Save changes"}</button><button type="button" className="coop-cancel-button" onClick={()=>setMemberForm(null)}>Cancel</button></div></form>}
<div className="coop-member-list">{filtered.map(r=><details className="coop-member-card" key={r.sn} open={!!openMember[r.sn]} onToggle={e=>setOpenMember(v=>({...v,[r.sn]:e.currentTarget.open}))}><summary><span>#{r.sn} {r.name}</span><span>{r.loanClosing<=0?"FULL PAYMENT":"Closing Loan: ₦"+moneyCell(r.loanClosing)}</span></summary><div className="coop-member-grid">
<div className="coop-member-metric"><span>Opening Savings</span><strong>₦{moneyCell(r.openingSaving)}</strong></div>
<div className="coop-member-metric"><span>{selectedMonth} Savings Collection</span><input aria-label={r.name+" savings collection"} type="number" min="0" value={r.savingCollection||0} disabled={selectedMonth==="July"} onChange={e=>updateEntry(r.sn,"savingCollection",e.target.value)}/></div>
<div className="coop-member-metric"><span>{selectedMonth} Savings Withdrawal</span><input aria-label={r.name+" savings withdrawal"} type="number" min="0" value={r.savingWithdrawal||0} disabled={selectedMonth==="July"} onChange={e=>updateEntry(r.sn,"savingWithdrawal",e.target.value)}/></div>
<div className="coop-member-metric net"><span>Closing Savings (automatic)</span><strong>₦{moneyCell(r.savingClosing)}</strong></div>
<div className="coop-member-metric loan"><span>Opening Loan Balance</span><strong>₦{moneyCell(r.openingLoan)}</strong></div>
<div className="coop-member-metric loan"><span>{selectedMonth} Loan Collection / Repayment</span><input aria-label={r.name+" loan collection"} type="number" min="0" value={r.loanCollection||0} disabled={selectedMonth==="July"} onChange={e=>updateEntry(r.sn,"loanCollection",e.target.value)}/></div>
<div className="coop-member-metric loan"><span>{selectedMonth} Additional Loan Paid</span><input aria-label={r.name+" additional loan paid"} type="number" min="0" value={r.loanPaid||0} disabled={selectedMonth==="July"} onChange={e=>updateEntry(r.sn,"loanPaid",e.target.value)}/></div>
<div className="coop-member-metric loan"><span>New Loan Issued</span><input aria-label={r.name+" new loan"} type="number" min="0" value={r.newLoan||0} disabled={selectedMonth==="July"} onChange={e=>updateEntry(r.sn,"newLoan",e.target.value)}/></div>
<div className="coop-member-metric net"><span>Closing Loan Balance (automatic)</span><strong>₦{moneyCell(r.loanClosing)}</strong></div>
<div className="coop-member-metric"><span>Payment Status</span><strong className={r.loanClosing<=0?"coop-paid-status":"coop-due-status"}>{r.loanClosing<=0?"FULL PAYMENT":"OUTSTANDING BALANCE"}</strong></div>
<div className="coop-member-metric"><span>Remark</span><strong>{r.remark||"-"}</strong></div>
</div><div className="coop-card-actions"><button type="button" className="coop-edit-button" onClick={()=>editMember(r.sn)}>✎ Edit member</button><button type="button" className="coop-delete-button" onClick={()=>deleteMember(r.sn)}>⌫ Delete member</button></div></details>)}</div>
<div className="coop-storage-note">{selectedMonth==="July"?"July figures are the original source schedule and remain unchanged.":"Monthly inputs are initialized at zero; balances carry forward from the prior month. Enter actual collections, withdrawals, repayments, or new loans to update balances."} A member receives <strong>FULL PAYMENT</strong> automatically when their calculated closing loan balance reaches ₦0. Changes are saved in this browser on this device only. They are not yet synced to the portal database or other devices.</div></div>
}

export default App;